mapper.select:
select id, house_id, rabbit_id, start_date, diagnosis, drug, dose, days, next_review_date, status, remark, request_id, create_by, create_time, update_by, update_time
from treatment_records
where house_id = #{houseId} and id = #{id}

select id, house_id, rabbit_id, start_date, diagnosis, drug, dose, days, next_review_date, status, remark, request_id, create_by, create_time, update_by, update_time
from treatment_records
where house_id = #{houseId} and rabbit_id = #{rabbitId}
